import json
obj=json.load(open('/app/benchmark/task_input.json'))
# show all interaction ids per page
from collections import defaultdict
m=defaultdict(list)
for it in obj['interactions']:
  m[it['page']].append((it['id'], it['type'], it['trigger']))
for page, items in m.items():
  print('\n',page)
  for i in items:
    print('-', i[0], '|', i[1])
PY"}

