import json
from pathlib import Path
from bs4 import BeautifulSoup
obj=json.load(open('/app/benchmark/task_input.json'))
base=Path('/app/output')

# Map page_id to filename
page_files={p['page_id']:p['file'] for p in obj['pages']}

# ensure interactions have corresponding data attributes elements
html_cache={}
for page_id, fname in page_files.items():
  soup=BeautifulSoup((base/fname).read_text('utf-8'),'html.parser')
  html_cache[page_id]=soup

issues=[]

# Check accordion pages specified by interactions
for it in obj['interactions']:
  soup=html_cache[it['page']]
  if it['type']=='toggle':
    if not soup.select_one('[data-accordion]'):
      issues.append((it['page'], it['id'], 'missing [data-accordion]'))
  if it['id'].endswith('carousel'):
    if not soup.select_one('[data-carousel]'):
      issues.append((it['page'], it['id'], 'missing [data-carousel]'))

# Check data_display expected content appears as text somewhere
for dd in obj['data_display']:
  soup=html_cache[dd['page']]
  text=soup.get_text(' ', strip=True)
  for item in dd['expected_content']:
    if item not in text:
      issues.append((dd['page'], dd['id'], f"missing content: {item}"))

print('issues count', len(issues))
for x in issues[:40]:
  print('-', x)
PY

